// Browser SFX adapter. Presentation-only; never imported by the engine.
// Soft arcade clips are generated by tools/generate-sfx.py.
const KEY = 'slidey_muted';
const BASE = 'assets/sfx/';

export const SFX = {
  click: 'click.wav',
  drag: 'drag.wav',
  trim: 'trim.wav',
  fall: 'fall.wav',
  clear: 'clear.wav',
  'totem-spawn': 'totem-spawn.wav',
  'totem-clear': 'totem-clear.wav',
  'totem-submit': 'totem-submit.wav',
  'totem-suction': 'totem-suction.wav',
  'god-clear': 'god-clear.wav',
  fail: 'fail.wav'
};

function browserStorage() {
  try { return globalThis.localStorage ?? null; } catch { return null; }
}

export function createAudio({
  storage = browserStorage(),
  AudioCtor = typeof Audio === 'undefined' ? null : Audio,
  ContextCtor = globalThis.AudioContext ?? globalThis.webkitAudioContext ?? null,
  fetcher = globalThis.fetch?.bind(globalThis),
  base = BASE
} = {}) {
  let muted = false;
  try { muted = storage?.getItem(KEY) === '1'; } catch {}
  const cache = new Map();
  const buffers = new Map();
  const loading = new Map();
  let context = null, unlocked = false;
  if (ContextCtor && fetcher) {
    try { context = new ContextCtor({ latencyHint: 'interactive' }); } catch {}
  }

  function src(name) {
    return base + (SFX[name] || name);
  }

  function loadClip(name) {
    if (!AudioCtor || cache.has(name)) return cache.get(name);
    const clip = new AudioCtor(src(name));
    clip.preload = 'auto';
    cache.set(name, clip);
    return clip;
  }

  function load(name) {
    if (!SFX[name]) return null;
    if (!context) return loadClip(name);
    if (!loading.has(name)) {
      loading.set(name, Promise.resolve().then(() => fetcher(src(name)))
        .then(response => {
          if (!response.ok) throw new Error('SFX unavailable');
          return response.arrayBuffer();
        })
        .then(data => context.decodeAudioData(data))
        .then(buffer => { buffers.set(name, buffer); return buffer; })
        .catch(() => {
          // Retain media-element playback if a browser cannot decode a clip.
          buffers.set(name, null);
          return null;
        }));
    }
    return loading.get(name);
  }

  function unlock() {
    unlocked = true;
    // Only input handlers call this. A blocked resume can stay pending, so a
    // fresh gesture must always be able to retry (especially touch release).
    if (context && context.state !== 'running') {
      try {
        Promise.resolve(context.resume()).catch(() => {});
      } catch {}
    }
  }

  function isMuted() {
    return muted;
  }

  function setMuted(next) {
    muted = !!next;
    try { storage?.setItem(KEY, muted ? '1' : '0'); } catch {}
    return muted;
  }

  function play(name, { volume = 1, rate = 1 } = {}) {
    if (muted || !unlocked || !SFX[name]) return false;
    volume = Math.max(0, Math.min(1, volume));
    rate = Math.max(0.7, Math.min(1.3, rate));
    if (context?.state === 'running' && buffers.get(name)) {
      const buffer = buffers.get(name);
      const source = context.createBufferSource();
      const gain = context.createGain();
      source.buffer = buffer;
      source.playbackRate.value = rate;
      gain.gain.value = volume;
      source.connect(gain);
      gain.connect(context.destination);
      source.onended = () => { source.disconnect(); gain.disconnect(); };
      source.start(context.currentTime);
      return true;
    }
    // Play this cue through the original adapter while Web Audio is loading or
    // suspended. Never queue it for a second playback when resume completes.
    const proto = loadClip(name);
    if (!proto) return false;
    const clip = proto.cloneNode ? proto.cloneNode() : new AudioCtor(src(name));
    clip.volume = volume;
    clip.playbackRate = rate;
    try { clip.currentTime = 0; } catch {}
    try {
      const started = clip.play?.();
      if (started && typeof started.catch === 'function') started.catch(() => {});
    } catch { return false; }
    return true;
  }

  // Fetch and decode before the first interaction, without starting playback.
  for (const name of Object.keys(SFX)) { loadClip(name); load(name); }
  return { play, unlock, isMuted, setMuted, load };
}

const audio = createAudio();
export const playSfx = (name, opts) => audio.play(name, opts);
export const unlockAudio = () => audio.unlock();
export const isMuted = () => audio.isMuted();
export const setMuted = next => audio.setMuted(next);
